import re, subprocess, glob

GITDIR='/tmp/shurik-workspace-U1tGte'
def git(*a): return subprocess.run(['git','-C',GITDIR]+list(a),capture_output=True,text=True).stdout

tips={b:git('rev-parse','origin/friend/'+b).strip() for b in ['rachel','monica','phoebe','joey','chandler','ross']}
entry_re=re.compile(r'^\*\*(?P<sp>[A-Za-z]+)\*\* \((?P<ts>[0-9T:\-Z]+)\)\n\nSource: friend/(?P<br>[a-z]+) @ (?P<sha>[0-9a-f]{40})\n\n(?P<text>(?:(?!\n\n\*\*|\n\n\*Editor).)*)',re.S|re.M)

problems=[];total=0;ep_counts={}
for path in sorted(glob.glob('/tmp/friends-main-edit/S*/E*.md')):
    txt=open(path,encoding='utf-8').read()
    for m in entry_re.finditer(txt):
        total+=1
        sp,ts,br,sha,text=m.group('sp'),m.group('ts'),m.group('br'),m.group('sha'),m.group('text').strip('\n')
        ep_counts[path.split('/')[-1]]=ep_counts.get(path.split('/')[-1],0)+1
        if subprocess.run(['git','-C',GITDIR,'cat-file','-e',sha+'^{commit}'],capture_output=True).returncode!=0:
            problems.append((path,sha,'MISSING COMMIT',sp));continue
        body=git('log','-1','--format=%B',sha)
        if subprocess.run(['git','-C',GITDIR,'merge-base','--is-ancestor',sha,tips[br]],capture_output=True).returncode!=0:
            problems.append((path,sha,'NOT ON BRANCH '+br,sp))
        if 'Friend-Message: 1' not in body: problems.append((path,sha,'NO FRIEND-MESSAGE',sp))
        msp=re.search(r'^Speaker: (\S+)$',body,re.M)
        if not msp or msp.group(1)!=sp: problems.append((path,sha,f'SPEAKER {msp.group(1) if msp else None}!={sp}',sp))
        parts=body.split('\n\n')
        utter='\n\n'.join(parts[2:]).strip('\n')
        if utter!=text: problems.append((path,sha,'TEXT MISMATCH',sp,repr(text[:50]),repr(utter[:50])))
        want=git('log','-1','--format=%cI',sha).strip()[:19]+'Z'
        if want!=ts: problems.append((path,sha,f'TS {ts}!={want}',sp))
print('entries checked:',total)
print('problems:',len(problems))
for p in problems[:30]:print(p)
print('sources per episode total:',sum(ep_counts.values()))
